    emb = self.item_emb(seq)
    # Row i counts matching items only at earlier positions j < i.
    matches = seq.unsqueeze(2).eq(seq.unsqueeze(1))
    repeats = torch.tril(matches, diagonal=-1).sum(dim=-1)
    repeats = repeats * seq.ne(0)
